import cyclopts

app = cyclopts.App(
    config_search_path=["."],
)

@app.default
def main(
    name: str = "World",
    count: int = 1,
    verbose: bool = False,
):
    """
    Greet with configuration from pyproject.toml [tool.mycli].

    Example pyproject.toml:
        [tool.mycli]
        name = "Alice"
        count = 3
        verbose = true
    """
    for i in range(count):
        msg = f"Hello, {name}!"
        if verbose:
            print(f"[Greeting {i+1}] {msg}")
        else:
            print(msg)

if __name__ == "__main__":
    app()
